const n = id => +String($(id).value).replace(',', '.'); const pT = v => { const m = String(v).match(/^(\d+)(?::(\d{1,2}))?$/); return m ? +m[1] + (+(m[2] || 0)) / 60 : NaN; }, fT = h => `${Math.floor(h)}:${String(Math.round(h % 1 * 60)).padStart(2, '0')}`;
