// --- лист документа A4 (JPEG): блоки {h}, {p}, {t:[[...]], w:[доли]}
function docSheet(title, blocks){ const W = 1240, H = 1754, M = 90, pages = []; let cv, g, y;
const st = S.stamp || {}, np = () => { cv = document.createElement('canvas'); cv.width = W; cv.height = H; g = cv.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, W, H); g.fillStyle = '#111'; g.textBaseline = 'top'; pages.push(cv);
if (st.gr){ g.font = '700 24px sans-serif'; g.textAlign = 'right'; g.fillText(st.gr, W - M, 40); } g.textAlign = 'left'; y = M; if (pages.length === 1){ g.font = '700 36px sans-serif'; g.textAlign = 'center'; wrap(title, W / 2, W - 2 * M, 44, true); g.textAlign = 'left'; y += 18; } };
const wrap = (t, x, w, lh, ctr) => { String(t).split('\n').forEach(par => { const ws = par.split(' '); let ln = ''; const flush = () => { if (y + lh > H - M - 40) np(); g.fillText(ln, x, y); y += lh; ln = ''; };
ws.forEach(wd => { const tt = ln ? ln + ' ' + wd : wd; if (g.measureText(tt).width > w && ln){ flush(); ln = wd; } else ln = tt; }); flush(); }); };
const lines = (t, w) => { const o = []; String(t ?? '').split('\n').forEach(par => { let ln = ''; par.split(' ').forEach(wd => { const tt = ln ? ln + ' ' + wd : wd; if (g.measureText(tt).width > w && ln){ o.push(ln); ln = wd; } else ln = tt; }); o.push(ln); }); return o; };
np(); blocks.forEach(b => { if (b.h){ if (y > H - M - 120) np(); y += 14; g.font = '700 28px sans-serif'; wrap(b.h, M, W - 2 * M, 36); y += 4; }
else if (b.p != null){ g.font = '400 25px sans-serif'; wrap(b.p || '—', M, W - 2 * M, 33); y += 8; }
else if (b.t){ const cols = b.t[0].length, wf = b.w || Array(cols).fill(1 / cols), cw = wf.map(f => f * (W - 2 * M)); g.lineWidth = 1.5; g.strokeStyle = '#333';
b.t.forEach((row, ri) => { g.font = `${ri === 0 && b.head !== false ? 700 : 400} 22px sans-serif`; const L1 = row.map((c, i) => lines(c, cw[i] - 14)), rh = Math.max(...L1.map(l => l.length)) * 28 + 12; if (y + rh > H - M - 40){ np(); }
let x = M; L1.forEach((l, i) => { g.strokeRect(x, y, cw[i], rh); l.forEach((s0, k) => g.fillText(s0, x + 7, y + 6 + k * 28)); x += cw[i]; }); y += rh; }); y += 14; } });
const n = pages.length; pages.forEach((c, i) => { const q = c.getContext('2d'); q.font = '400 20px sans-serif'; q.fillStyle = '#555'; q.textAlign = 'left'; q.textBaseline = 'bottom'; q.fillText(`${st.isp ? 'Исполнитель: ' + st.isp + ' · ' : ''}${dt(now())}`, M, H - 40); q.textAlign = 'right'; q.fillText(`Лист ${i + 1} из ${n}`, W - M, H - 40); }); return pages; }
async function docSave(title, blocks, nm){ const P0 = docSheet(title, blocks); for (let i = 0; i < P0.length; i++){ const bl = await new Promise(r => P0[i].toBlob(r, 'image/jpeg', .9)); deliverFile(bl, `СКАТ_${nm}_${stamp()}${P0.length > 1 ? '_л' + (i + 1) : ''}.jpg`, P0.length > 1 ? `Лист ${i + 1} из ${P0.length} готов` : 'Лист готов'); if (i < P0.length - 1) await new Promise(r => setTimeout(r, 900)); } }
